from dsl import Course
c = Course("faelle", name="Fallwerkstatt", short="Fälle", term="Modul Grundsicherung", lecturer="Teamteaching",
           exams=[], accent="#17614A", lineTitle="Die Fälle", stopWord="Fall",
           openName="Rasterfrage", openNamePl="Rasterfragen", openLead="",
           ranks=[[0,"Praktikum"],[100,"Erstgespräch"],[300,"Fallführung"],[650,"Vernetzung"],[1100,"Intervision"],[1700,"Teamleitung"],[2500,"Fachaufsicht"]],
           modes=["cases","blitz"], source="9 Teamteaching-Fälle, Übungsfall und Fall Sozialzentrum nach dem Fallanalyseraster. Die Lösungspunkte hat Claude aus Präsentation, Skripten und Fernlehren abgeleitet; sie stammen nicht von den Lehrenden.")
CH,T,MC,TF,ORD,MATCH,MULTI,BUCKET,CHAIN = c.CH,c.T,c.MC,c.TF,c.ORD,c.MATCH,c.MULTI,c.BUCKET,c.CHAIN

SECTIONS = [
 dict(n=1,key="auftrag",title="Auftrag, Angebot, Zielgruppe",prompt="Was ist Auftrag, Angebot und Zielgruppe deiner Einrichtung?"),
 dict(n=2,key="situation",title="Situation und Problem",prompt="Wie stellt sich die Situation dar? Problem, Hypothesen, Dynamiken, Gefährdungen."),
 dict(n=3,key="ressourcen",title="Ressourcen",prompt="Welche institutionellen, finanziellen und lebensweltlichen Ressourcen gibt es? Wen vernetzt du?"),
 dict(n=4,key="ziele",title="Ziele",prompt="Kurz-, mittel- und langfristige Ziele. Wo weichen Klient*in, du und die Organisation voneinander ab?"),
 dict(n=5,key="plan",title="Handlungsplan",prompt="Was tust du sofort, kurz-, mittel- und langfristig? Welche Variante, und warum?"),
 dict(n=6,key="grenzen",title="Grenzen",prompt="Was kannst du nach deinem Ausbildungsstand noch nicht bearbeiten?"),
]
CASES = []
def CASE(id, doc, title, where, who, lead, tags, sections, chain, triage, why_tri):
    src=[(doc,1)]
    CH(id,title,where,who,[doc])
    T("f-"+id,id,title,lead,src)
    out={}
    for k,pts in sections.items():
        out[k]=[dict(t=p[0],src=p[1],lens=(p[2] if len(p)>2 else None)) for p in pts]
    CASES.append(dict(id=id,doc=doc,title=title,where=where,who=who,lead=lead,tags=tags,sections=out))
    CHAIN("f-"+id,[],f"Fallkette: {title}",lead,chain,"Jede Frage greift ein Detail aus dem Fall auf und prüft das Fachwissen dahinter: Fristen, Zuständigkeiten, Anrechnung und Ansprüche. Im Fallanalyseraster gehört dieses Wissen vor allem zu den Ressourcen und zum Handlungsplan; die Erklärungen zu den einzelnen Schritten zeigen, wo es in den Unterlagen steht.")
    ORD("f-"+id,[],f"{title}: Was kommt zuerst?",triage,why_tri,src+[("msk",106)],hint="Von dringend zu weniger dringend.")

T("f-raster","raster","Das Fallanalyseraster","Sechs Punkte: Auftrag, Angebot und Zielgruppe; soziale Situation mit Hypothesen, Dynamiken und Gefährdungen; Ressourcen; Ziele mit Zieldifferenzen; Handlungsplan mit Begründung und Varianten; Grenzen des Ausbildungsstands.",[("cr",1)])
CH("raster","Das Raster","Fallanalyseraster","Sechs Schritte",["cr"])
ORD("f-raster",[],"Bring das Raster in die richtige Reihenfolge.",["Auftrag, Angebot, Zielgruppe","Soziale Situation und Problem","Ressourcen","Ziele","Handlungsplan und Lösungsansätze","Was noch nicht bearbeitet werden kann"],"So steht es im Fallanalyseraster: Erst klärst du Auftrag, Angebot und Zielgruppe deiner Einrichtung, dann die soziale Situation mit Hypothesen, Dynamiken und Gefährdungen, dann die Ressourcen. Darauf bauen Ziele und Handlungsplan auf, und am Ende benennst du ehrlich, was du nach deinem Ausbildungsstand noch nicht bearbeiten kannst.",[("cr",1)])
BUCKET("f-raster",[],"Zu welchem Schritt des Fallanalyserasters gehört diese Angabe?",["2 Situation","3 Ressourcen","4 Ziele","5 Plan"],[("Vorläufige Erklärung im Sinn einer Hypothese",0),("Gefährdungen",0),("Vernetzungsmöglichkeiten",1),("Lebensweltliche Unterstützung",1),("Zieldifferenzen",2),("Kurzfristig, mittelfristig, langfristig unterschiedene Ziele",2),("Methodisches Vorgehen mit Begründung",3),("Mehrere Varianten, eine gewählt",3)],"Die Unterpunkte stehen wörtlich im Raster. Hypothesen und Gefährdungen beschreiben die Situation in Punkt 2, Vernetzung und lebensweltliche Unterstützung sind Ressourcen in Punkt 3. Zieldifferenzen und die Unterscheidung von kurz-, mittel- und langfristig gehören zu den Zielen, methodisches Vorgehen mit Begründung und mehrere Varianten zum Handlungsplan.",[("cr",1)])
MULTI("f-raster",[],"Welche Ressourcenarten nennt das Raster?",["Institutionell","Finanziell","Lebensweltlich","Vernetzung"],["Politisch","Kulturell"],"Punkt 3 des Rasters nennt institutionelle, finanzielle und lebensweltliche Ressourcen sowie Vernetzungsmöglichkeiten. Lebensweltlich heißt etwa Familie, Freund*innen, Nachbarschaft oder eigene Fähigkeiten der Klient*innen. Finanzielle Ressourcen sind in der Grundsicherung oft der Kern: welche Ansprüche bestehen und noch nicht genutzt werden.",[("cr",1)])
TF("f-raster",[],"Das Raster verlangt, Zieldifferenzen zwischen Klient*in, Sozialarbeiter*in und Organisation zu benennen.",True,"Das verlangt Punkt 4 des Rasters. In fast jedem Fall gibt es solche Differenzen: Herr C. will rasch eine billige Wohnung, die Einrichtung muss zuerst seinen Lebensmittelpunkt klären. Wer sie offen benennt, kann realistisch planen und erklärt der Klientin, warum etwas länger dauert.",[("cr",1)])

